/**
 * MediaPipe's `facialTransformationMatrixes[i].data` is a length-16 array in
 * column-major order (matches WebGL, three.js). Element at row `r`, column `c`
 * lives at index `c * 4 + r`.
 */
const el = (m: ArrayLike<number>, r: number, c: number): number => {
  const v = m[c * 4 + r];
  return v ?? 0;
};

const clamp = (v: number, lo: number, hi: number): number =>
  Math.max(lo, Math.min(hi, v));

export interface EulerYXZ {
  yaw: number;
  pitch: number;
  roll: number;
}

/**
 * Decompose the rotation part of a 4x4 matrix into YXZ intrinsic Tait-Bryan
 * angles: apply yaw (around Y), then pitch (around X), then roll (around Z).
 *
 * This matches the natural head-pose decomposition where yaw = shake-head-no,
 * pitch = nod-yes, roll = tilt-to-shoulder. Outputs are in radians.
 *
 * Math: for R = Ry * Rx * Rz we have R[1][2] = -sin(pitch),
 * R[0][2] = sin(yaw)*cos(pitch), R[2][2] = cos(yaw)*cos(pitch),
 * R[1][0] = cos(pitch)*sin(roll), R[1][1] = cos(pitch)*cos(roll).
 */
export const extractEulerYXZ = (m: ArrayLike<number>): EulerYXZ => {
  const pitch = Math.asin(clamp(-el(m, 1, 2), -1, 1));
  const cosPitch = Math.cos(pitch);
  if (Math.abs(cosPitch) > 1e-6) {
    return {
      pitch,
      yaw: Math.atan2(el(m, 0, 2), el(m, 2, 2)),
      roll: Math.atan2(el(m, 1, 0), el(m, 1, 1)),
    };
  }
  // Gimbal lock: fall back to yaw-only solution.
  return {
    pitch,
    yaw: Math.atan2(-el(m, 2, 0), el(m, 0, 0)),
    roll: 0,
  };
};

/** Radians → degrees, for display. */
export const toDegrees = (radians: number): number => (radians * 180) / Math.PI;

/**
 * Produce a 4x4 column-major matrix whose rotation part is `refᵀ · cur`,
 * i.e. the rotation of `cur` expressed in the frame defined by `ref`.
 *
 * Used for calibration: if `ref` is captured as the user's neutral pose, then
 * `relativeRotation(ref, cur)` yields the deviation from neutral. When
 * `cur === ref`, the result is the identity (yaw = pitch = roll = 0).
 *
 * Only the upper-left 3x3 is meaningful; translation is zeroed and the
 * homogeneous element is 1.
 */
export const relativeRotation = (
  ref: ArrayLike<number>,
  cur: ArrayLike<number>,
): Float32Array => {
  const out = new Float32Array(16);
  // Column-major indexing: row r, col c → index c*4+r.
  // refᵀ[r][k] = ref[k][r] = ref[r*4+k]
  // cur[k][c]  = cur[c*4+k]
  for (let r = 0; r < 3; r++) {
    for (let c = 0; c < 3; c++) {
      let sum = 0;
      for (let k = 0; k < 3; k++) {
        sum += (ref[r * 4 + k] ?? 0) * (cur[c * 4 + k] ?? 0);
      }
      out[c * 4 + r] = sum;
    }
  }
  out[15] = 1;
  return out;
};
